/* Placement English: eight self-contained 50-question banks. */
function englishAssessment(id, rows, makeQuestion) {
  return rows.map((row, index) => {
    const item = makeQuestion(row, index);
    const shift = item.options.length ? (index * 7 + 2) % item.options.length : 0;
    const orderedTexts = item.options.slice(shift).concat(item.options.slice(0, shift));
    const options = orderedTexts.map((text, optionIndex) => ({ key: String.fromCharCode(97 + optionIndex), text }));
    const answer = options.find(option => option.text === item.answer)?.key;
    return { id: `english_${id}_${index + 1}`, qNum: `Question ${index + 1}`, prompt: item.prompt, options, answer, hint: item.hint, kapilTip: item.explanation };
  });
}

